Policies/ReportPolicy.php
<?php
// app/Policies/ReportPolicy.php

namespace App\Policies;

use App\Models\User;
use App\Models\Report;
use Illuminate\Auth\Access\Response;

class ReportPolicy
{
    /**
     * Determine if the user can view any reports.
     */
    public function viewAny(User $user): bool
    {
        // All authenticated users can view their reports list
        return true;
    }

    /**
     * Determine if the user can view the report.
     */
    public function view(User $user, Report $report): bool
    {
        // User can view their own reports OR admin can view all
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can create reports.
     */
    public function create(User $user): bool
    {
        // All authenticated users can create reports
        return true;
    }

    /**
     * Determine if the user can update the report.
     */
    public function update(User $user, Report $report): bool
    {
        // User can update their own reports OR admin can update all
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can delete the report.
     */
    public function delete(User $user, Report $report): bool
    {
        // User can delete their own reports OR admin can delete all
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can restore the report.
     */
    public function restore(User $user, Report $report): bool
    {
        // For soft deletes (if you implement them)
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can permanently delete the report.
     */
    public function forceDelete(User $user, Report $report): bool
    {
        // For permanent deletion
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can publish the report.
     */
    public function publish(User $user, Report $report): bool
    {
        // User can publish their own draft reports
        return $user->id === $report->user_id && $report->status === 'draft';
    }

    /**
     * Determine if the user can archive the report.
     */
    public function archive(User $user, Report $report): bool
    {
        // User can archive their own reports (except archived ones)
        return $user->id === $report->user_id && $report->status !== 'archived';
    }

    /**
     * Determine if the user can duplicate the report.
     */
    public function duplicate(User $user, Report $report): bool
    {
        // User can duplicate their own reports OR admin can duplicate all
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can export the report.
     */
    public function export(User $user, Report $report): bool
    {
        // User can export their own reports OR admin can export all
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can share the report.
     */
    public function share(User $user, Report $report): bool
    {
        // User can share their own published reports
        return $user->id === $report->user_id && $report->status === 'published';
    }

    /**
     * Determine if the user can view report versions.
     */
    public function viewVersions(User $user, Report $report): bool
    {
        // User can view versions of their own reports OR admin can view all
        return $user->id === $report->user_id || $user->hasRole('admin');
    }

    /**
     * Determine if the user can restore a version.
     */
    public function restoreVersion(User $user, Report $report): bool
    {
        // User can restore versions of their own reports OR admin can restore all
        return $user->id === $report->user_id || $user->hasRole('admin');
    }
}

Providers/AppServiceProvider.php
<?php
// app/Providers/AppServiceProvider.php

namespace App\Providers;

use Illuminate\Support\ServiceProvider;
use Illuminate\Support\Facades\Blade;
use Illuminate\Support\Facades\Gate;
use Illuminate\Pagination\Paginator;
use Illuminate\Support\Facades\URL;
use Illuminate\Support\Facades\View;
use App\Models\Report;
use App\Models\User;
use App\Models\Task;

class AppServiceProvider extends ServiceProvider
{
    /**
     * Register any application services.
     */
    public function register(): void
    {
        //
    }

    /**
     * Bootstrap any application services.
     */
    public function boot(): void
    {
        // Use Bootstrap 5 for pagination styling
        Paginator::useBootstrapFive();
        
        // Force HTTPS in production
        if (config('app.env') === 'production') {
            URL::forceScheme('https');
        }

        // ─────────────────────────────────────────────────────────────
        //  BLADE DIRECTIVES FOR PERMISSION CHECKS
        // ─────────────────────────────────────────────────────────────

        // Check if user can update a report
        Blade::if('canUpdate', function ($report) {
            if (!auth()->check()) return false;
            
            $user = auth()->user();
            
            // Admin can update anything
            if ($user->hasRole('admin')) return true;
            
            // Owner can update
            if ($user->id === $report->user_id) return true;
            
            // Check assignment permissions
            $assignment = \App\Models\ReportAssignment::where('report_id', $report->id)
                ->where('user_id', $user->id)
                ->where('is_active', true)
                ->where(function($q) {
                    $q->whereNull('expires_at')->orWhere('expires_at', '>', now());
                })
                ->first();
                
            return $assignment && in_array($assignment->permission, ['edit', 'manage']);
        });

        // Check if user can delete a report
        Blade::if('canDelete', function ($report) {
            if (!auth()->check()) return false;
            
            $user = auth()->user();
            
            // Admin can delete anything
            if ($user->hasRole('admin')) return true;
            
            // Only owner can delete
            return $user->id === $report->user_id && $report->status !== 'published';
        });

        // Check if user can share a report
        Blade::if('canShare', function ($report) {
            if (!auth()->check()) return false;
            
            $user = auth()->user();
            
            // Admin can share anything
            if ($user->hasRole('admin')) return true;
            
            // Owner can share published reports
            return $user->id === $report->user_id && $report->status === 'published';
        });

        // Check if user can view a report
        Blade::if('canView', function ($report) {
            if (!auth()->check()) return false;
            
            $user = auth()->user();
            
            // Admin can view anything
            if ($user->hasRole('admin')) return true;
            
            // Owner can view
            if ($user->id === $report->user_id) return true;
            
            // Check if user has assignment
            $hasAccess = \App\Models\ReportAssignment::where('report_id', $report->id)
                ->where('user_id', $user->id)
                ->where('is_active', true)
                ->where(function($q) {
                    $q->whereNull('expires_at')->orWhere('expires_at', '>', now());
                })
                ->exists();
                
            // Check if report is publicly shared
            return $hasAccess || $report->is_public;
        });

        // Check if user can manage reports (assign to others)
        Blade::if('canManageReports', function () {
            if (!auth()->check()) return false;
            
            $user = auth()->user();
            return $user->hasRole('admin') || $user->hasRole('manager');
        });

        // Check if user can manage tasks
        Blade::if('canManageTasks', function () {
            if (!auth()->check()) return false;
            
            $user = auth()->user();
            return $user->hasRole('admin') || $user->hasRole('manager');
        });

        // Check if user can manage users
        Blade::if('canManageUsers', function () {
            if (!auth()->check()) return false;
            
            $user = auth()->user();
            return $user->hasRole('admin');
        });

        // Check if user is admin
        Blade::if('isAdmin', function () {
            if (!auth()->check()) return false;
            return auth()->user()->hasRole('admin');
        });

        // Check if user is manager
        Blade::if('isManager', function () {
            if (!auth()->check()) return false;
            return auth()->user()->hasRole('manager');
        });

        // Check if user is premium
        Blade::if('isPremium', function () {
            if (!auth()->check()) return false;
            return auth()->user()->is_premium;
        });

        // ─────────────────────────────────────────────────────────────
        //  VIEW COMPOSERS (Share data with all views)
        // ─────────────────────────────────────────────────────────────
        View::composer('*', function ($view) {
            if (auth()->check()) {
                $user = auth()->user();
                
                // Share task counts
                $view->with('pendingTasksCount', $user->getPendingTasksCount());
                $view->with('overdueTasksCount', $user->getOverdueTasksCount());
                
                // Share assigned reports count
                $assignedReports = \App\Models\ReportAssignment::where('user_id', $user->id)
                    ->where('is_active', true)
                    ->where(function($q) {
                        $q->whereNull('expires_at')->orWhere('expires_at', '>', now());
                    })
                    ->count();
                $view->with('assignedReportsCount', $assignedReports);
            }
        });
    }
}
Providers/AuthserviceProvider.php
<?php
// app/Providers/AuthServiceProvider.php

namespace App\Providers;

use App\Models\Report;
use App\Policies\ReportPolicy;
use Illuminate\Foundation\Support\Providers\AuthServiceProvider as ServiceProvider;
use Illuminate\Support\Facades\Gate;
use App\Models\User;

class AuthServiceProvider extends ServiceProvider
{
    protected $policies = [
        Report::class => ReportPolicy::class,
    ];

    public function boot(): void
    {
        $this->registerPolicies();

        // Super admin gate - allows admin to do everything
        Gate::before(function ($user, $ability) {
            if ($user->hasRole('admin')) {
                return true;
            }
        });

        // Impersonation gate
        Gate::define('impersonate', function (User $user, User $target) {
            return $user->hasRole('admin') && $user->id !== $target->id;
        });

        // Stop impersonation gate
        Gate::define('stopImpersonate', function (User $user) {
            return session()->has('impersonate');
        });

        // Report access gates
        Gate::define('view-report', function (User $user, Report $report) {
            return $user->canAccessReport($report, 'view');
        });

        Gate::define('edit-report', function (User $user, Report $report) {
            return $user->canAccessReport($report, 'edit');
        });

        Gate::define('manage-report', function (User $user, Report $report) {
            return $user->canAccessReport($report, 'manage');
        });
    }
}

Services/notificationService.php

<?php
// app/Services/NotificationService.php

namespace App\Services;

use App\Models\Notification;
use App\Models\User;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Log;

class NotificationService
{
    /**
     * Create a new notification.
     */
    public static function create(
        User|int $user,
        string $type,
        string $title,
        string $message,
        $notifiable = null,
        ?string $actionUrl = null,
        ?string $icon = null,
        ?string $color = null,
        ?array $data = null
    ): ?Notification {
        try {
            $userId = $user instanceof User ? $user->id : $user;

            return Notification::create([
                'user_id' => $userId,
                'type' => $type,
                'title' => $title,
                'message' => $message,
                'notifiable_type' => $notifiable ? get_class($notifiable) : null,
                'notifiable_id' => $notifiable ? $notifiable->id : null,
                'action_url' => $actionUrl,
                'icon' => $icon ?? self::getDefaultIcon($type),
                'color' => $color ?? self::getDefaultColor($type),
                'data' => $data,
            ]);
        } catch (\Exception $e) {
            Log::error('Failed to create notification: ' . $e->getMessage());
            return null;
        }
    }

    /**
     * Notify multiple users at once.
     */
    public static function notifyMany(
        array $userIds,
        string $type,
        string $title,
        string $message,
        $notifiable = null,
        ?string $actionUrl = null,
        ?string $icon = null,
        ?string $color = null,
        ?array $data = null
    ): void {
        $notifications = array_map(function ($userId) use ($type, $title, $message, $notifiable, $actionUrl, $icon, $color, $data) {
            return [
                'user_id' => $userId,
                'type' => $type,
                'title' => $title,
                'message' => $message,
                'notifiable_type' => $notifiable ? get_class($notifiable) : null,
                'notifiable_id' => $notifiable ? $notifiable->id : null,
                'action_url' => $actionUrl,
                'icon' => $icon ?? self::getDefaultIcon($type),
                'color' => $color ?? self::getDefaultColor($type),
                'data' => json_encode($data),
                'created_at' => now(),
                'updated_at' => now(),
            ];
        }, $userIds);

        DB::table('notifications')->insert($notifications);
    }

    /**
     * Create notification when a task is created.
     */
    public static function taskCreated($task, $assignedTo = null): void
    {
        $assignedUser = $assignedTo ?? $task->assigned_to;
        if ($assignedUser) {
            $userId = $assignedUser instanceof User ? $assignedUser->id : $assignedUser;
            self::create(
                user: $userId,
                type: 'task_created',
                title: 'New Task Assigned',
                message: "Task \"{$task->title}\" has been assigned to you.",
                notifiable: $task,
                actionUrl: route('admin.tasks.my'),
                icon: 'fa-solid fa-tasks',
                color: '#6366f1'
            );
        }

        // Notify admins
        $admins = User::role('admin')->pluck('id')->toArray();
        if (!empty($admins)) {
            self::notifyMany(
                userIds: $admins,
                type: 'task_created',
                title: 'New Task Created',
                message: "Task \"{$task->title}\" has been created by " . auth()->user()->name,
                notifiable: $task,
                actionUrl: route('admin.tasks.index'),
                icon: 'fa-solid fa-tasks',
                color: '#6366f1'
            );
        }
    }

    /**
     * Create notification when a task is completed.
     */
    public static function taskCompleted($task): void
    {
        $admins = User::role('admin')->pluck('id')->toArray();
        if (!empty($admins)) {
            self::notifyMany(
                userIds: $admins,
                type: 'task_completed',
                title: 'Task Completed',
                message: "Task \"{$task->title}\" has been completed by " . auth()->user()->name,
                notifiable: $task,
                actionUrl: route('admin.tasks.index'),
                icon: 'fa-solid fa-check-circle',
                color: '#10b981'
            );
        }
    }

    /**
     * Create notification when a report is assigned.
     */
    public static function reportAssigned($report, $assignedTo): void
    {
        $userId = $assignedTo instanceof User ? $assignedTo->id : $assignedTo;
        self::create(
            user: $userId,
            type: 'report_assigned',
            title: 'Report Assigned to You',
            message: "Report \"{$report->title}\" has been assigned to you by " . auth()->user()->name,
            notifiable: $report,
            actionUrl: route('reports.preview', $report->slug),
            icon: 'fa-solid fa-share-alt',
            color: '#8b5cf6'
        );
    }

    /**
     * Create notification when a report is shared.
     */
    public static function reportShared($report, $sharedWith): void
    {
        $userId = $sharedWith instanceof User ? $sharedWith->id : $sharedWith;
        self::create(
            user: $userId,
            type: 'report_shared',
            title: 'Report Shared with You',
            message: "Report \"{$report->title}\" has been shared with you.",
            notifiable: $report,
            actionUrl: route('reports.preview', $report->slug),
            icon: 'fa-solid fa-share-nodes',
            color: '#06b6d4'
        );
    }

    /**
     * Create notification when a report is updated.
     */
    public static function reportUpdated($report, $updatedBy = null): void
    {
        $updater = $updatedBy ?? auth()->user();
        
        // Notify the report owner if someone else updated it
        if ($report->user_id !== $updater->id) {
            self::create(
                user: $report->user_id,
                type: 'report_updated',
                title: 'Report Updated',
                message: "Your report \"{$report->title}\" was updated by {$updater->name}.",
                notifiable: $report,
                actionUrl: route('reports.preview', $report->slug),
                icon: 'fa-solid fa-pen-to-square',
                color: '#f59e0b'
            );
        }
    }

    /**
     * Create notification when a user is mentioned.
     */
    public static function userMentioned($mentionedUser, $report = null, $comment = null): void
    {
        $userId = $mentionedUser instanceof User ? $mentionedUser->id : $mentionedUser;
        self::create(
            user: $userId,
            type: 'user_mentioned',
            title: 'You Were Mentioned',
            message: auth()->user()->name . " mentioned you" . ($report ? " in report \"{$report->title}\"" : "") . ".",
            notifiable: $report,
            actionUrl: $report ? route('reports.preview', $report->slug) : null,
            icon: 'fa-solid fa-at',
            color: '#ec4899'
        );
    }

    /**
     * Soft delete all notifications for a notifiable entity.
     */
    public static function deleteForNotifiable($notifiable): void
    {
        Notification::where('notifiable_type', get_class($notifiable))
            ->where('notifiable_id', $notifiable->id)
            ->delete();
    }

    /**
     * Restore all notifications for a notifiable entity.
     */
    public static function restoreForNotifiable($notifiable): void
    {
        Notification::withTrashed()
            ->where('notifiable_type', get_class($notifiable))
            ->where('notifiable_id', $notifiable->id)
            ->restore();
    }

    /**
     * Force delete all notifications for a notifiable entity.
     */
    public static function forceDeleteForNotifiable($notifiable): void
    {
        Notification::withTrashed()
            ->where('notifiable_type', get_class($notifiable))
            ->where('notifiable_id', $notifiable->id)
            ->forceDelete();
    }

    /**
     * Get default icon based on notification type.
     */
    private static function getDefaultIcon(string $type): string
    {
        return match ($type) {
            'task_created' => 'fa-solid fa-tasks',
            'task_completed' => 'fa-solid fa-check-circle',
            'task_updated' => 'fa-solid fa-pen-to-square',
            'task_deleted' => 'fa-solid fa-trash',
            'task_restored' => 'fa-solid fa-rotate-left',
            'report_assigned' => 'fa-solid fa-share-alt',
            'report_shared' => 'fa-solid fa-share-nodes',
            'report_created' => 'fa-solid fa-file-pen',
            'report_updated' => 'fa-solid fa-pen-to-square',
            'report_deleted' => 'fa-solid fa-trash',
            'report_restored' => 'fa-solid fa-rotate-left',
            'user_mentioned' => 'fa-solid fa-at',
            'system' => 'fa-solid fa-gear',
            default => 'fa-solid fa-bell',
        };
    }

    /**
     * Get default color based on notification type.
     */
    private static function getDefaultColor(string $type): string
    {
        return match ($type) {
            'task_created', 'task_updated' => '#6366f1', // Indigo
            'task_completed' => '#10b981', // Emerald
            'task_deleted' => '#ef4444', // Red
            'task_restored' => '#f59e0b', // Amber
            'report_assigned' => '#8b5cf6', // Violet
            'report_shared' => '#06b6d4', // Cyan
            'report_created' => '#f59e0b', // Amber
            'report_updated' => '#3b82f6', // Blue
            'report_deleted' => '#ef4444', // Red
            'report_restored' => '#10b981', // Emerald
            'user_mentioned' => '#ec4899', // Pink
            'system' => '#64748b', // Slate
            default => '#64748b', // Slate
        };
    }
}
Middleware/HandleInertiaRequest.php
<?php
// app/Http/Middleware/HandleInertiaRequests.php

namespace App\Http\Middleware;

use Illuminate\Http\Request;
use Inertia\Middleware;
use App\Models\Task;
use App\Models\ReportAssignment;
use App\Models\Notification;

class HandleInertiaRequests extends Middleware
{
    /**
     * The root template that is loaded on the first page visit.
     *
     * @var string
     */
    protected $rootView = 'app';

    /**
     * Determine the current asset version.
     */
    public function version(Request $request): ?string
    {
        return parent::version($request);
    }

    /**
     * Define the props that are shared by default.
     *
     * @return array<string, mixed>
     */
    public function share(Request $request): array
    {
        $user = $request->user();
        
        // Get user-specific data (only if authenticated)
        $pendingTasks = null;
        $overdueTasks = null;
        $assignedReportsCount = null;
        $notifications = [];
        $unreadNotificationsCount = 0;
        $notificationTypes = [];
        
        if ($user) {
            // Count pending tasks for notification badge
            $pendingTasks = Task::where('assigned_to', $user->id)
                ->whereIn('status', ['pending', 'in_progress'])
                ->count();
            
            // Count overdue tasks
            $overdueTasks = Task::where('assigned_to', $user->id)
                ->where('status', '!=', 'completed')
                ->where('due_date', '<', now())
                ->count();
            
            // Count assigned reports
            $assignedReportsCount = ReportAssignment::where('user_id', $user->id)
                ->where('is_active', true)
                ->where(function($q) {
                    $q->whereNull('expires_at')->orWhere('expires_at', '>', now());
                })
                ->count();
            
            // Get latest notifications for dropdown
            $notifications = Notification::where('user_id', $user->id)
                ->recent()
                ->take(10)
                ->get()
                ->map(function ($notification) {
                    return [
                        'id' => $notification->id,
                        'type' => $notification->type,
                        'title' => $notification->title,
                        'message' => $notification->message,
                        'icon' => $notification->icon ?? 'fa-solid fa-bell',
                        'color' => $notification->color ?? '#64748b',
                        'action_url' => $notification->action_url,
                        'read_at' => $notification->read_at,
                        'trashed' => $notification->trashed(),
                        'created_at' => $notification->created_at,
                        'time_ago' => $notification->created_at->diffForHumans(),
                    ];
                });
            
            // Get unread notification count
            $unreadNotificationsCount = Notification::where('user_id', $user->id)
                ->whereNull('read_at')
                ->count();
            
            // Get notification type counts for filtering
            $notificationTypes = Notification::where('user_id', $user->id)
                ->whereNull('read_at')
                ->selectRaw('type, COUNT(*) as count')
                ->groupBy('type')
                ->pluck('count', 'type')
                ->toArray();
            
            // Get specific notification counts for sidebar badges
            $assignedReportsNotifications = Notification::where('user_id', $user->id)
                ->whereNull('read_at')
                ->whereIn('type', ['report_assigned', 'report_shared'])
                ->count();
            
            $pendingTaskNotifications = Notification::where('user_id', $user->id)
                ->whereNull('read_at')
                ->whereIn('type', ['task_created', 'task_updated'])
                ->count();
        }
        
        return [
            ...parent::share($request),
            'auth' => [
                'user' => $user ? [
                    'id' => $user->id,
                    'name' => $user->name,
                    'email' => $user->email,
                    'is_premium' => $user->is_premium,
                    'roles' => $user->getRoleNames(),
                ] : null,
                'is_impersonating' => session()->has('impersonate'),
            ],
            'flash' => [
                'success' => session('success'),
                'error' => session('error'),
                'warning' => session('warning'),
                'info' => session('info'),
            ],
            'app' => [
                'name' => config('app.name'),
                'environment' => config('app.env'),
                'url' => config('app.url'),
                'version' => '1.0.0',
            ],
            'notifications' => [
                'pending_tasks' => $pendingTasks,
                'overdue_tasks' => $overdueTasks,
                'assigned_reports' => $assignedReportsCount,
                // New dynamic notification data
                'items' => $notifications,
                'unread_count' => $unreadNotificationsCount,
                'types' => $notificationTypes,
                'assigned_reports_notifications' => $assignedReportsNotifications ?? 0,
                'pending_task_notifications' => $pendingTaskNotifications ?? 0,
            ],
        ];
    }
}

Middleware/Authenticate.ph
<?php

namespace App\Http\Middleware;

use Illuminate\Auth\Middleware\Authenticate as Middleware;

class Authenticate extends Middleware
{
    /**
     * Get the path the user should be redirected to when they are not authenticated.
     */
    protected function redirectTo($request)
    {
        if (!$request->expectsJson()) {
            return route('login');
        }
    }
}
controllers/admin/ActivityController.php
<?php
// app/Http/Controllers/Admin/ActivityController.php

namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Models\UserActivity;
use App\Models\User;
use Illuminate\Http\Request;
use Inertia\Inertia;
use Illuminate\Support\Facades\DB;
use Carbon\Carbon;

class ActivityController extends Controller
{
  

    /**
     * Display all activities
     */
    public function index(Request $request)
    {
        $activities = UserActivity::with('user')
            ->when($request->action, fn($q) => $q->where('action', $request->action))
            ->when($request->user_id, fn($q) => $q->where('user_id', $request->user_id))
            ->when($request->search, fn($q) => $q->whereHas('user', fn($sq) => 
                $sq->where('name', 'like', "%{$request->search}%")
                    ->orWhere('email', 'like', "%{$request->search}%")
            ))
            ->when($request->date_from, fn($q) => $q->whereDate('created_at', '>=', $request->date_from))
            ->when($request->date_to, fn($q) => $q->whereDate('created_at', '<=', $request->date_to))
            ->orderBy($request->sort ?? 'created_at', $request->direction ?? 'desc')
            ->paginate(25)
            ->through(fn($activity) => [
                'id' => $activity->id,
                'action' => $activity->action,
                'entity_type' => $activity->entity_type,
                'entity_id' => $activity->entity_id,
                'details' => $activity->details,
                'ip_address' => $activity->ip_address,
                'user_agent' => $activity->user_agent,
                'created_at' => $activity->created_at,
                'user' => $activity->user ? [
                    'id' => $activity->user->id,
                    'name' => $activity->user->name,
                    'email' => $activity->user->email,
                ] : null,
            ]);

        $users = User::all(['id', 'name', 'email']);
        
        $actions = UserActivity::distinct()->pluck('action');
        
        $stats = [
            'total' => UserActivity::count(),
            'today' => UserActivity::whereDate('created_at', today())->count(),
            'this_week' => UserActivity::whereBetween('created_at', [Carbon::now()->startOfWeek(), Carbon::now()->endOfWeek()])->count(),
            'this_month' => UserActivity::whereMonth('created_at', Carbon::now()->month)->count(),
        ];

        return Inertia::render('Admin/Activities/Index', [
            'activities' => $activities,
            'users' => $users,
            'actions' => $actions,
            'stats' => $stats,
            'filters' => $request->only(['action', 'user_id', 'search', 'date_from', 'date_to', 'sort', 'direction']),
        ]);
    }

    /**
     * Get activities for a specific user
     */
    public function userActivities(User $user, Request $request)
    {
        $activities = UserActivity::where('user_id', $user->id)
            ->when($request->action, fn($q) => $q->where('action', $request->action))
            ->orderBy($request->sort ?? 'created_at', $request->direction ?? 'desc')
            ->paginate(20)
            ->through(fn($activity) => [
                'id' => $activity->id,
                'action' => $activity->action,
                'entity_type' => $activity->entity_type,
                'details' => $activity->details,
                'ip_address' => $activity->ip_address,
                'created_at' => $activity->created_at,
            ]);

        $stats = [
            'total' => UserActivity::where('user_id', $user->id)->count(),
            'last_activity' => UserActivity::where('user_id', $user->id)->latest()->first()?->created_at,
            'actions' => UserActivity::where('user_id', $user->id)
                ->select('action', DB::raw('count(*) as count'))
                ->groupBy('action')
                ->get(),
        ];

        return response()->json([
            'activities' => $activities,
            'stats' => $stats,
        ]);
    }

    /**
     * Clear old activities
     */
    public function clear(Request $request)
    {
        $request->validate([
            'days' => 'required|integer|min:1|max:365',
        ]);

        $deleted = UserActivity::where('created_at', '<', Carbon::now()->subDays($request->days))->delete();

        // Log this action
        UserActivity::log(auth()->id(), 'activities_cleared', 'system', null, [
            'days' => $request->days,
            'deleted_count' => $deleted,
        ]);

        return back()->with('success', "Deleted {$deleted} activity records older than {$request->days} days.");
    }

    /**
     * Export activities
     */
    public function export(Request $request)
    {
        $query = UserActivity::with('user');
        
        if ($request->date_from) {
            $query->whereDate('created_at', '>=', $request->date_from);
        }
        if ($request->date_to) {
            $query->whereDate('created_at', '<=', $request->date_to);
        }
        if ($request->action) {
            $query->where('action', $request->action);
        }
        if ($request->user_id) {
            $query->where('user_id', $request->user_id);
        }

        $activities = $query->orderBy('created_at', 'desc')->get();

        $filename = 'activities_export_' . now()->format('Y-m-d_H-i-s') . '.csv';
        $callback = function() use ($activities) {
            $handle = fopen('php://output', 'w');
            fputcsv($handle, ['User', 'Action', 'Entity Type', 'Details', 'IP Address', 'User Agent', 'Timestamp']);
            
            foreach ($activities as $activity) {
                fputcsv($handle, [
                    $activity->user->name ?? 'System',
                    $activity->action,
                    $activity->entity_type ?? 'N/A',
                    json_encode($activity->details),
                    $activity->ip_address ?? 'N/A',
                    $activity->user_agent ?? 'N/A',
                    $activity->created_at,
                ]);
            }
            fclose($handle);
        };
        
        return response()->stream($callback, 200, [
            'Content-Type' => 'text/csv',
            'Content-Disposition' => 'attachment; filename="' . $filename . '"',
        ]);
    }

    /**
     * Get activity statistics
     */
    public function getStats()
    {
        $stats = [
            'by_action' => UserActivity::select('action', DB::raw('count(*) as count'))
                ->groupBy('action')
                ->orderBy('count', 'desc')
                ->get(),
            'by_hour' => UserActivity::select(DB::raw('HOUR(created_at) as hour'), DB::raw('count(*) as count'))
                ->groupBy('hour')
                ->orderBy('hour')
                ->get(),
            'by_day' => UserActivity::select(DB::raw('DATE(created_at) as date'), DB::raw('count(*) as count'))
                ->where('created_at', '>=', Carbon::now()->subDays(30))
                ->groupBy('date')
                ->orderBy('date')
                ->get(),
        ];

        return response()->json($stats);
    }
}

admin/AnalyticsController.php
<?php
// app/Http/Controllers/Admin/AnalyticsController.php

namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Models\Report;
use App\Models\User;
use App\Models\Task;
use App\Models\UserActivity;
use App\Models\ReportAssignment;
use Illuminate\Http\Request;
use Inertia\Inertia;
use Illuminate\Support\Facades\DB;
use Carbon\Carbon;

class AnalyticsController extends Controller
{
   

    /**
     * Display analytics dashboard
     */
    public function index(Request $request)
    {
        $period = $request->get('period', '30');
        $startDate = Carbon::now()->subDays($period);
        
        // Report statistics
        $reportStats = [
            'total' => Report::count(),
            'published' => Report::where('status', 'published')->count(),
            'draft' => Report::where('status', 'draft')->count(),
            'archived' => Report::where('status', 'archived')->count(),
            'trend' => $this->getReportTrend($startDate),
        ];
        
        // User statistics
        $userStats = [
            'total' => User::count(),
            'new_this_month' => User::whereMonth('created_at', Carbon::now()->month)->count(),
            'active' => User::where('email_verified_at', '!=', null)->count(),
            'premium' => User::where('is_premium', true)->count(),
            'with_reports' => User::has('reports')->count(),
        ];
        
        // Task statistics
        $taskStats = [
            'total' => Task::count(),
            'completed' => Task::where('status', 'completed')->count(),
            'pending' => Task::where('status', 'pending')->count(),
            'in_progress' => Task::where('status', 'in_progress')->count(),
            'overdue' => Task::where('status', '!=', 'completed')
                ->where('due_date', '<', now())
                ->count(),
            'completion_rate' => $this->calculateCompletionRate(),
        ];
        
        // Activity statistics
        $activityStats = [
            'total' => UserActivity::count(),
            'last_24h' => UserActivity::where('created_at', '>=', Carbon::now()->subDay())->count(),
            'last_7d' => UserActivity::where('created_at', '>=', Carbon::now()->subDays(7))->count(),
            'most_active_users' => $this->getMostActiveUsers(),
        ];
        
        // Chart data
        $chartData = [
            'reports_created' => $this->getReportsCreatedChart($startDate),
            'user_growth' => $this->getUserGrowthChart($startDate),
            'task_completion' => $this->getTaskCompletionChart($startDate),
            'popular_report_types' => $this->getPopularReportTypes(),
        ];
        
        // Sharing statistics
        $sharingStats = [
            'total_shares' => ReportAssignment::count(),
            'active_shares' => ReportAssignment::where('is_active', true)->count(),
            'expired_shares' => ReportAssignment::where('expires_at', '<', now())->count(),
            'most_shared_reports' => $this->getMostSharedReports(),
        ];
        
        return Inertia::render('Admin/Analytics/Index', [
            'reportStats' => $reportStats,
            'userStats' => $userStats,
            'taskStats' => $taskStats,
            'activityStats' => $activityStats,
            'sharingStats' => $sharingStats,
            'chartData' => $chartData,
            'period' => $period,
        ]);
    }
    
    /**
     * Get detailed reports analytics
     */
    public function reports(Request $request)
    {
        $period = $request->get('period', '30');
        $startDate = Carbon::now()->subDays($period);
        
        $reports = Report::with('user')
            ->when($request->status, fn($q) => $q->where('status', $request->status))
            ->when($request->search, fn($q) => $q->where('title', 'like', "%{$request->search}%"))
            ->orderBy($request->sort ?? 'created_at', $request->direction ?? 'desc')
            ->paginate(20)
            ->through(fn($report) => [
                'id' => $report->id,
                'title' => $report->title,
                'status' => $report->status,
                'user_name' => $report->user->name,
                'pages' => count($report->content ?? []),
                'shares' => $report->assignments()->count(),
                'created_at' => $report->created_at,
                'updated_at' => $report->updated_at,
            ]);
        
        $summary = [
            'total_pages' => Report::sum(DB::raw('JSON_LENGTH(content)')),
            'avg_pages_per_report' => round(Report::avg(DB::raw('JSON_LENGTH(content)')), 1),
            'total_shares' => ReportAssignment::count(),
            'reports_with_shares' => Report::has('assignments')->count(),
        ];
        
        return Inertia::render('Admin/Analytics/Reports', [
            'reports' => $reports,
            'summary' => $summary,
            'filters' => $request->only(['status', 'search', 'sort', 'direction']),
        ]);
    }
    
    /**
     * Get detailed users analytics
     */
    public function users(Request $request)
    {
        $users = User::withCount(['reports', 'tasksAssigned', 'tasksCreated'])
            ->when($request->search, fn($q) => $q->where('name', 'like', "%{$request->search}%")
                ->orWhere('email', 'like', "%{$request->search}%"))
            ->when($request->role, fn($q) => $q->role($request->role))
            ->orderBy($request->sort ?? 'created_at', $request->direction ?? 'desc')
            ->paginate(20)
            ->through(fn($user) => [
                'id' => $user->id,
                'name' => $user->name,
                'email' => $user->email,
                'reports_count' => $user->reports_count,
                'tasks_assigned' => $user->tasks_assigned_count,
                'tasks_created' => $user->tasks_created_count,
                'last_activity' => $user->activities()->latest()->first()?->created_at,
                'created_at' => $user->created_at,
            ]);
        
        $summary = [
            'total_users' => User::count(),
            'users_with_reports' => User::has('reports')->count(),
            'users_with_tasks' => User::has('tasksAssigned')->count(),
            'avg_reports_per_user' => round(User::avg(DB::raw('(SELECT COUNT(*) FROM reports WHERE reports.user_id = users.id)')), 1),
        ];
        
        $roles = \Spatie\Permission\Models\Role::all();
        
        return Inertia::render('Admin/Analytics/Users', [
            'users' => $users,
            'summary' => $summary,
            'roles' => $roles,
            'filters' => $request->only(['search', 'role', 'sort', 'direction']),
        ]);
    }
    
    /**
     * Export analytics data
     */
    public function export(Request $request)
    {
        $type = $request->get('type', 'reports');
        $period = $request->get('period', '30');
        $startDate = Carbon::now()->subDays($period);
        
        if ($type === 'reports') {
            return $this->exportReportsData($startDate);
        } elseif ($type === 'users') {
            return $this->exportUsersData($startDate);
        } elseif ($type === 'tasks') {
            return $this->exportTasksData($startDate);
        } elseif ($type === 'activities') {
            return $this->exportActivitiesData($startDate);
        }
        
        return response()->json(['error' => 'Invalid export type'], 422);
    }
    
    /**
     * Get API stats for dashboard widgets
     */
    public function quickStats()
    {
        return response()->json([
            'reports' => [
                'total' => Report::count(),
                'today' => Report::whereDate('created_at', today())->count(),
                'this_week' => Report::whereBetween('created_at', [Carbon::now()->startOfWeek(), Carbon::now()->endOfWeek()])->count(),
            ],
            'users' => [
                'total' => User::count(),
                'new_today' => User::whereDate('created_at', today())->count(),
                'active' => User::whereNotNull('email_verified_at')->count(),
            ],
            'tasks' => [
                'completed' => Task::where('status', 'completed')->whereDate('completed_at', today())->count(),
                'pending' => Task::where('status', 'pending')->count(),
                'overdue' => Task::where('status', '!=', 'completed')->where('due_date', '<', now())->count(),
            ],
        ]);
    }
    
    // ─────────────────────────────────────────────────────────────
    // PRIVATE HELPER METHODS
    // ─────────────────────────────────────────────────────────────
    
    private function getReportTrend($startDate)
    {
        $previousPeriod = Carbon::now()->subDays(30);
        $currentCount = Report::where('created_at', '>=', $startDate)->count();
        $previousCount = Report::whereBetween('created_at', [$previousPeriod, $startDate])->count();
        
        if ($previousCount == 0) return 100;
        return round((($currentCount - $previousCount) / $previousCount) * 100, 1);
    }
    
    private function calculateCompletionRate()
    {
        $total = Task::count();
        if ($total == 0) return 0;
        $completed = Task::where('status', 'completed')->count();
        return round(($completed / $total) * 100, 1);
    }
    
    private function getMostActiveUsers()
    {
        return UserActivity::select('user_id', DB::raw('count(*) as activity_count'))
            ->with('user')
            ->groupBy('user_id')
            ->orderBy('activity_count', 'desc')
            ->limit(5)
            ->get()
            ->map(fn($activity) => [
                'user_id' => $activity->user_id,
                'user_name' => $activity->user->name,
                'activity_count' => $activity->activity_count,
            ]);
    }
    
    private function getReportsCreatedChart($startDate)
    {
        $dates = [];
        $counts = [];
        
        for ($i = 0; $i <= 30; $i++) {
            $date = Carbon::now()->subDays($i);
            $dates[] = $date->format('M d');
            $counts[] = Report::whereDate('created_at', $date)->count();
        }
        
        return [
            'labels' => array_reverse($dates),
            'values' => array_reverse($counts),
        ];
    }
    
    private function getUserGrowthChart($startDate)
    {
        $dates = [];
        $counts = [];
        
        for ($i = 0; $i <= 30; $i++) {
            $date = Carbon::now()->subDays($i);
            $dates[] = $date->format('M d');
            $counts[] = User::whereDate('created_at', $date)->count();
        }
        
        return [
            'labels' => array_reverse($dates),
            'values' => array_reverse($counts),
        ];
    }
    
    private function getTaskCompletionChart($startDate)
    {
        $dates = [];
        $completed = [];
        $created = [];
        
        for ($i = 0; $i <= 30; $i++) {
            $date = Carbon::now()->subDays($i);
            $dates[] = $date->format('M d');
            $completed[] = Task::whereDate('completed_at', $date)->count();
            $created[] = Task::whereDate('created_at', $date)->count();
        }
        
        return [
            'labels' => array_reverse($dates),
            'completed' => array_reverse($completed),
            'created' => array_reverse($created),
        ];
    }
    
    private function getPopularReportTypes()
    {
        // This is simplified - you can expand based on your template system
        return [
            'labels' => ['Business', 'Executive', 'Analytics', 'Marketing', 'Financial'],
            'values' => [45, 30, 25, 20, 15],
        ];
    }
    
    private function getMostSharedReports()
    {
        return Report::withCount('assignments')
            ->orderBy('assignments_count', 'desc')
            ->limit(5)
            ->get()
            ->map(fn($report) => [
                'title' => $report->title,
                'share_count' => $report->assignments_count,
            ]);
    }
    
    private function exportReportsData($startDate)
    {
        $reports = Report::with('user')
            ->where('created_at', '>=', $startDate)
            ->get();
        
        $filename = 'reports_analytics_' . now()->format('Y-m-d') . '.csv';
        $callback = function() use ($reports) {
            $handle = fopen('php://output', 'w');
            fputcsv($handle, ['Title', 'Author', 'Status', 'Pages', 'Shares', 'Created At', 'Updated At']);
            
            foreach ($reports as $report) {
                fputcsv($handle, [
                    $report->title,
                    $report->user->name,
                    $report->status,
                    count($report->content ?? []),
                    $report->assignments()->count(),
                    $report->created_at,
                    $report->updated_at,
                ]);
            }
            fclose($handle);
        };
        
        return response()->stream($callback, 200, [
            'Content-Type' => 'text/csv',
            'Content-Disposition' => 'attachment; filename="' . $filename . '"',
        ]);
    }
    
    private function exportUsersData($startDate)
    {
        $users = User::withCount(['reports', 'tasksAssigned'])
            ->where('created_at', '>=', $startDate)
            ->get();
        
        $filename = 'users_analytics_' . now()->format('Y-m-d') . '.csv';
        $callback = function() use ($users) {
            $handle = fopen('php://output', 'w');
            fputcsv($handle, ['Name', 'Email', 'Reports Created', 'Tasks Assigned', 'Joined', 'Last Activity']);
            
            foreach ($users as $user) {
                fputcsv($handle, [
                    $user->name,
                    $user->email,
                    $user->reports_count,
                    $user->tasks_assigned_count,
                    $user->created_at,
                    $user->activities()->latest()->first()?->created_at ?? 'N/A',
                ]);
            }
            fclose($handle);
        };
        
        return response()->stream($callback, 200, [
            'Content-Type' => 'text/csv',
            'Content-Disposition' => 'attachment; filename="' . $filename . '"',
        ]);
    }
    
    private function exportTasksData($startDate)
    {
        $tasks = Task::with(['assignedTo', 'assignedBy'])
            ->where('created_at', '>=', $startDate)
            ->get();
        
        $filename = 'tasks_analytics_' . now()->format('Y-m-d') . '.csv';
        $callback = function() use ($tasks) {
            $handle = fopen('php://output', 'w');
            fputcsv($handle, ['Title', 'Assigned To', 'Assigned By', 'Priority', 'Status', 'Due Date', 'Completed At']);
            
            foreach ($tasks as $task) {
                fputcsv($handle, [
                    $task->title,
                    $task->assignedTo->name,
                    $task->assignedBy->name,
                    $task->priority,
                    $task->status,
                    $task->due_date ?? 'N/A',
                    $task->completed_at ?? 'N/A',
                ]);
            }
            fclose($handle);
        };
        
        return response()->stream($callback, 200, [
            'Content-Type' => 'text/csv',
            'Content-Disposition' => 'attachment; filename="' . $filename . '"',
        ]);
    }
    
    private function exportActivitiesData($startDate)
    {
        $activities = UserActivity::with('user')
            ->where('created_at', '>=', $startDate)
            ->orderBy('created_at', 'desc')
            ->get();
        
        $filename = 'activities_analytics_' . now()->format('Y-m-d') . '.csv';
        $callback = function() use ($activities) {
            $handle = fopen('php://output', 'w');
            fputcsv($handle, ['User', 'Action', 'Entity Type', 'Details', 'IP Address', 'Timestamp']);
            
            foreach ($activities as $activity) {
                fputcsv($handle, [
                    $activity->user->name,
                    $activity->action,
                    $activity->entity_type ?? 'N/A',
                    json_encode($activity->details),
                    $activity->ip_address ?? 'N/A',
                    $activity->created_at,
                ]);
            }
            fclose($handle);
        };
        
        return response()->stream($callback, 200, [
            'Content-Type' => 'text/csv',
            'Content-Disposition' => 'attachment; filename="' . $filename . '"',
        ]);
    }
}
admin/ReportAssignmentController.php
<?php
// app/Http/Controllers/Admin/ReportAssignmentController.php

namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Models\Report;
use App\Models\User;
use App\Models\ReportAssignment;
use App\Models\UserActivity;
use Illuminate\Http\Request;
use Inertia\Inertia;

class ReportAssignmentController extends Controller
{

    public function index(Request $request)
    {
        $assignments = ReportAssignment::with(['report', 'user', 'assignedBy'])
            ->when($request->report_id, fn($q) => $q->where('report_id', $request->report_id))
            ->when($request->user_id, fn($q) => $q->where('user_id', $request->user_id))
            ->orderBy('assigned_at', 'desc')
            ->paginate(20)
            ->withQueryString();

        $reports = Report::all();
        $users = User::all();

        return Inertia::render('Admin/Reports/Assignments', [
            'assignments' => $assignments,
            'reports' => $reports,
            'users' => $users,
            'filters' => $request->only(['report_id', 'user_id'])
        ]);
    }

    public function store(Request $request)
    {
        $request->validate([
            'report_id' => 'required|exists:reports,id',
            'user_id' => 'required|exists:users,id',
            'permission' => 'required|in:view,edit,manage',
            'expires_at' => 'nullable|date|after:today',
        ]);

        $existing = ReportAssignment::where('report_id', $request->report_id)
            ->where('user_id', $request->user_id)
            ->first();

        if ($existing) {
            $existing->update([
                'permission' => $request->permission,
                'expires_at' => $request->expires_at,
                'is_active' => true,
            ]);
            $message = 'Assignment updated successfully.';
        } else {
            ReportAssignment::create([
                'report_id' => $request->report_id,
                'user_id' => $request->user_id,
                'assigned_by' => auth()->id(),
                'permission' => $request->permission,
                'expires_at' => $request->expires_at,
            ]);
            $message = 'Report assigned successfully.';
        }

        $report = Report::find($request->report_id);
        $user = User::find($request->user_id);

        UserActivity::log(auth()->id(), 'report_assigned', 'report', $report->id, [
            'report_title' => $report->title,
            'assigned_to' => $user->name,
            'permission' => $request->permission
        ]);

        return redirect()->back()->with('success', $message);
    }

    public function destroy(ReportAssignment $assignment)
    {
        $assignment->delete();

        UserActivity::log(auth()->id(), 'report_unassigned', 'report', $assignment->report_id, [
            'report_title' => $assignment->report->title,
            'user' => $assignment->user->name
        ]);

        return redirect()->back()->with('success', 'Assignment removed successfully.');
    }

    public function toggleActive(ReportAssignment $assignment)
    {
        $assignment->update(['is_active' => !$assignment->is_active]);

        return response()->json([
            'message' => $assignment->is_active ? 'Assignment activated.' : 'Assignment deactivated.'
        ]);
    }
}

admin/RoleController
<?php

namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Models\User;
use App\Models\UserActivity;
use Illuminate\Http\Request;
use Inertia\Inertia;
use Spatie\Permission\Models\Role;
use Spatie\Permission\Models\Permission;
use Illuminate\Validation\Rule;

class RoleController extends Controller
{
   
    /**
     * Display a listing of roles.
     */
    public function index(Request $request)
    {
        $roles = Role::with('permissions')
            ->when($request->search, function($query, $search) {
                $query->where('name', 'like', "%{$search}%");
            })
            ->orderBy($request->sort ?? 'name', $request->direction ?? 'asc')
            ->paginate(10)
            ->through(function($role) {
                return [
                    'id' => $role->id,
                    'name' => $role->name,
                    'guard_name' => $role->guard_name,
                    'permissions_count' => $role->permissions->count(),
                    'users_count' => $role->users()->count(),
                    'created_at' => $role->created_at,
                    'updated_at' => $role->updated_at,
                ];
            });

        $permissions = Permission::all()->groupBy(function($permission) {
            $parts = explode('-', $permission->name);
            return ucfirst($parts[0] ?? 'general');
        });

        $stats = [
            'total_roles' => Role::count(),
            'total_permissions' => Permission::count(),
            'total_users_with_roles' => User::role(Role::all())->count(),
        ];

        return Inertia::render('Admin/Roles/Index', [
            'roles' => $roles,
            'permissions' => $permissions,
            'stats' => $stats,
            'filters' => $request->only(['search', 'sort', 'direction'])
        ]);
    }

    /**
     * Show the form for creating a new role.
     */
    public function create()
    {
        $permissions = Permission::all()->groupBy(function($permission) {
            $parts = explode('-', $permission->name);
            return ucfirst($parts[0] ?? 'general');
        });

        return Inertia::render('Admin/Roles/Create', [
            'permissions' => $permissions
        ]);
    }

    /**
     * Store a newly created role in storage.
     */
    public function store(Request $request)
    {
        $request->validate([
            'name' => 'required|string|max:255|unique:roles,name',
            'permissions' => 'array',
            'permissions.*' => 'exists:permissions,name',
        ]);

        $role = Role::create([
            'name' => $request->name,
            'guard_name' => 'web',
        ]);

        if ($request->has('permissions')) {
            $role->syncPermissions($request->permissions);
        }

        UserActivity::log(auth()->id(), 'role_created', 'role', $role->id, [
            'role_name' => $role->name,
            'permissions_count' => count($request->permissions ?? [])
        ]);

        return redirect()->route('admin.roles.index')
            ->with('success', 'Role created successfully.');
    }

    /**
     * Display the specified role.
     */
    public function show(Role $role)
    {
        $role->load('permissions', 'users');
        
        $permissions = Permission::all()->groupBy(function($permission) {
            $parts = explode('-', $permission->name);
            return ucfirst($parts[0] ?? 'general');
        });

        $rolePermissions = $role->permissions->pluck('name')->toArray();

        return Inertia::render('Admin/Roles/Show', [
            'role' => [
                'id' => $role->id,
                'name' => $role->name,
                'guard_name' => $role->guard_name,
                'created_at' => $role->created_at,
                'updated_at' => $role->updated_at,
                'permissions' => $rolePermissions,
                'users_count' => $role->users()->count(),
            ],
            'permissions' => $permissions,
            'users' => $role->users()->take(10)->get(['id', 'name', 'email']),
        ]);
    }

    /**
     * Show the form for editing the specified role.
     */
    public function edit(Role $role)
    {
        $permissions = Permission::all()->groupBy(function($permission) {
            $parts = explode('-', $permission->name);
            return ucfirst($parts[0] ?? 'general');
        });

        $rolePermissions = $role->permissions->pluck('name')->toArray();

        return Inertia::render('Admin/Roles/Edit', [
            'role' => [
                'id' => $role->id,
                'name' => $role->name,
                'guard_name' => $role->guard_name,
            ],
            'permissions' => $permissions,
            'rolePermissions' => $rolePermissions,
        ]);
    }

    /**
     * Update the specified role in storage.
     */
    public function update(Request $request, Role $role)
    {
        $request->validate([
            'name' => [
                'required',
                'string',
                'max:255',
                Rule::unique('roles')->ignore($role->id),
            ],
            'permissions' => 'array',
            'permissions.*' => 'exists:permissions,name',
        ]);

        // Prevent changing admin role name
        if ($role->name === 'admin' && $request->name !== 'admin') {
            return back()->with('error', 'Cannot rename the admin role.');
        }

        $oldName = $role->name;
        $role->update([
            'name' => $request->name,
        ]);

        if ($request->has('permissions')) {
            $role->syncPermissions($request->permissions);
        }

        UserActivity::log(auth()->id(), 'role_updated', 'role', $role->id, [
            'old_name' => $oldName,
            'new_name' => $role->name,
            'permissions_count' => count($request->permissions ?? [])
        ]);

        return redirect()->route('admin.roles.index')
            ->with('success', 'Role updated successfully.');
    }

    /**
     * Remove the specified role from storage.
     */
    public function destroy(Role $role)
    {
        // Prevent deletion of admin role
        if ($role->name === 'admin') {
            return back()->with('error', 'Cannot delete the admin role.');
        }

        // Check if role has users
        if ($role->users()->count() > 0) {
            return back()->with('error', 'Cannot delete role with assigned users. Remove users from this role first.');
        }

        $roleName = $role->name;
        
        UserActivity::log(auth()->id(), 'role_deleted', 'role', $role->id, [
            'role_name' => $roleName
        ]);

        $role->delete();

        return redirect()->route('admin.roles.index')
            ->with('success', 'Role deleted successfully.');
    }

    /**
     * Display permissions management page.
     */
    public function permissions(Request $request)
    {
        $permissions = Permission::orderBy('name')->get()->groupBy(function($permission) {
            $parts = explode('-', $permission->name);
            return ucfirst($parts[0] ?? 'general');
        });

        $stats = [
            'total_permissions' => Permission::count(),
            'total_roles' => Role::count(),
            'permissions_by_group' => $permissions->map(fn($group) => $group->count()),
        ];

        return Inertia::render('Admin/Roles/Permissions', [
            'permissions' => $permissions,
            'stats' => $stats,
        ]);
    }

    /**
     * Create a new permission.
     */
    public function storePermission(Request $request)
    {
        $request->validate([
            'name' => 'required|string|max:255|unique:permissions,name',
            'group' => 'nullable|string|max:100',
        ]);

        $permission = Permission::create([
            'name' => $request->name,
            'guard_name' => 'web',
        ]);

        UserActivity::log(auth()->id(), 'permission_created', 'permission', $permission->id, [
            'permission_name' => $permission->name,
            'group' => $request->group
        ]);

        return redirect()->route('admin.roles.permissions')
            ->with('success', 'Permission created successfully.');
    }

    /**
     * Update a permission.
     */
    public function updatePermission(Request $request, Permission $permission)
    {
        $request->validate([
            'name' => [
                'required',
                'string',
                'max:255',
                Rule::unique('permissions')->ignore($permission->id),
            ],
        ]);

        $oldName = $permission->name;
        $permission->update(['name' => $request->name]);

        UserActivity::log(auth()->id(), 'permission_updated', 'permission', $permission->id, [
            'old_name' => $oldName,
            'new_name' => $permission->name
        ]);

        return redirect()->route('admin.roles.permissions')
            ->with('success', 'Permission updated successfully.');
    }

    /**
     * Delete a permission.
     */
    public function destroyPermission(Permission $permission)
    {
        // Check if permission is assigned to any role
        $rolesWithPermission = Role::whereHas('permissions', function($query) use ($permission) {
            $query->where('permission_id', $permission->id);
        })->count();

        if ($rolesWithPermission > 0) {
            return back()->with('error', 'Cannot delete permission that is assigned to roles.');
        }

        $permissionName = $permission->name;
        
        UserActivity::log(auth()->id(), 'permission_deleted', 'permission', $permission->id, [
            'permission_name' => $permissionName
        ]);

        $permission->delete();

        return redirect()->route('admin.roles.permissions')
            ->with('success', 'Permission deleted successfully.');
    }

    /**
     * Assign permissions to role in bulk.
     */
    public function assignPermissions(Request $request, Role $role)
    {
        $request->validate([
            'permissions' => 'required|array',
            'permissions.*' => 'exists:permissions,name',
        ]);

        $role->syncPermissions($request->permissions);

        UserActivity::log(auth()->id(), 'permissions_assigned', 'role', $role->id, [
            'role_name' => $role->name,
            'permissions_count' => count($request->permissions)
        ]);

        return response()->json([
            'message' => 'Permissions assigned successfully.',
            'permissions_count' => $role->permissions()->count()
        ]);
    }

    /**
     * Remove a specific permission from role.
     */
    public function removePermission(Role $role, Permission $permission)
    {
        $role->revokePermissionTo($permission);

        UserActivity::log(auth()->id(), 'permission_removed', 'role', $role->id, [
            'role_name' => $role->name,
            'permission_name' => $permission->name
        ]);

        return response()->json(['message' => 'Permission removed successfully.']);
    }

    /**
     * Get users with specific role.
     */
    public function roleUsers(Role $role)
    {
        $users = $role->users()->paginate(15);

        return response()->json([
            'users' => $users,
            'total' => $users->total(),
        ]);
    }

    /**
     * Assign role to user.
     */
    public function assignToUser(Request $request)
    {
        $request->validate([
            'user_id' => 'required|exists:users,id',
            'role_id' => 'required|exists:roles,id',
        ]);

        $user = User::findOrFail($request->user_id);
        $role = Role::findOrFail($request->role_id);

        // Prevent assigning admin role to non-admin users? (Optional)
        if ($role->name === 'admin' && !auth()->user()->hasRole('admin')) {
            return response()->json(['error' => 'Only administrators can assign the admin role.'], 403);
        }

        $user->assignRole($role);

        UserActivity::log(auth()->id(), 'role_assigned_to_user', 'user', $user->id, [
            'user_name' => $user->name,
            'role_name' => $role->name
        ]);

        return response()->json(['message' => 'Role assigned successfully.']);
    }

    /**
     * Remove role from user.
     */
    public function removeFromUser(Request $request)
    {
        $request->validate([
            'user_id' => 'required|exists:users,id',
            'role_id' => 'required|exists:roles,id',
        ]);

        $user = User::findOrFail($request->user_id);
        $role = Role::findOrFail($request->role_id);

        // Prevent removing own admin role
        if ($user->id === auth()->id() && $role->name === 'admin') {
            return response()->json(['error' => 'You cannot remove your own admin role.'], 403);
        }

        $user->removeRole($role);

        UserActivity::log(auth()->id(), 'role_removed_from_user', 'user', $user->id, [
            'user_name' => $user->name,
            'role_name' => $role->name
        ]);

        return response()->json(['message' => 'Role removed successfully.']);
    }

    /**
     * Get all available permissions grouped by category.
     */
    public function getAllPermissions()
    {
        $permissions = Permission::all()->map(function($permission) {
            $category = explode('-', $permission->name)[0];
            return [
                'id' => $permission->id,
                'name' => $permission->name,
                'category' => ucfirst($category),
            ];
        })->groupBy('category');

        return response()->json($permissions);
    }

    /**
     * Create default roles and permissions (for setup).
     */
    public function setupDefaultRoles()
    {
        // Only allow in development or by super admin
        if (!app()->environment('local') && !auth()->user()->hasRole('super-admin')) {
            return response()->json(['error' => 'Unauthorized'], 403);
        }

        $permissions = [
            // User management
            'view-users', 'create-users', 'edit-users', 'delete-users', 'manage-users',
            
            // Report management
            'view-reports', 'create-reports', 'edit-reports', 'delete-reports', 
            'manage-reports', 'assign-reports',
            
            // Task management
            'view-tasks', 'create-tasks', 'edit-tasks', 'delete-tasks', 'manage-tasks',
            
            // Template management
            'view-templates', 'create-templates', 'edit-templates', 'delete-templates',
            
            // Settings
            'manage-settings', 'view-analytics',
        ];

        foreach ($permissions as $permission) {
            Permission::findOrCreate($permission);
        }

        // Create roles
        $adminRole = Role::findOrCreate('admin');
        $managerRole = Role::findOrCreate('manager');
        $userRole = Role::findOrCreate('user');

        // Assign permissions
        $adminRole->givePermissionTo(Permission::all());
        
        $managerRole->givePermissionTo([
            'view-users', 'view-reports', 'create-reports', 'edit-reports',
            'assign-reports', 'view-tasks', 'create-tasks', 'edit-tasks',
            'manage-tasks', 'view-templates', 'view-analytics',
        ]);
        
        $userRole->givePermissionTo([
            'view-reports', 'create-reports', 'edit-reports', 'view-tasks', 'view-templates',
        ]);

        UserActivity::log(auth()->id(), 'default_roles_setup', 'system', null, [
            'roles_created' => ['admin', 'manager', 'user'],
            'permissions_created' => count($permissions)
        ]);

        return response()->json([
            'message' => 'Default roles and permissions created successfully.',
            'roles' => ['admin', 'manager', 'user'],
            'permissions_count' => count($permissions)
        ]);
    }

    /**
     * Get role statistics.
     */
    public function getStats()
    {
        $stats = [
            'total_roles' => Role::count(),
            'total_permissions' => Permission::count(),
            'total_users_with_roles' => User::role(Role::all())->count(),
            'roles_distribution' => Role::withCount('users')->get()->map(function($role) {
                return [
                    'name' => $role->name,
                    'users_count' => $role->users_count,
                ];
            }),
            'permissions_distribution' => Permission::withCount('roles')->get()->map(function($permission) {
                return [
                    'name' => $permission->name,
                    'roles_count' => $permission->roles_count,
                ];
            })->groupBy(function($item) {
                return explode('-', $item['name'])[0];
            }),
        ];

        return response()->json($stats);
    }
}

admin/TaskController.php
<?php
// app/Http/Controllers/Admin/TaskController.php

namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Models\Task;
use App\Models\Report;
use App\Models\User;
use App\Models\UserActivity;
use App\Services\NotificationService;
use Illuminate\Http\Request;
use Inertia\Inertia;

class TaskController extends Controller
{
    /**
     * Display a listing of tasks (Admin view)
     */
    public function index(Request $request)
    {
        $tasks = Task::with(['assignedTo', 'assignedBy', 'report'])
            ->when($request->status, fn($q) => $q->where('status', $request->status))
            ->when($request->priority, fn($q) => $q->where('priority', $request->priority))
            ->when($request->assigned_to, fn($q) => $q->where('assigned_to', $request->assigned_to))
            ->when($request->search, fn($q) => $q->where('title', 'like', "%{$request->search}%"))
            ->when($request->trashed, fn($q) => $q->onlyTrashed())
            ->orderBy($request->sort ?? 'created_at', $request->direction ?? 'desc')
            ->paginate(15)
            ->withQueryString()
            ->through(fn($task) => [
                'id' => $task->id,
                'title' => $task->title,
                'description' => $task->description,
                'priority' => $task->priority,
                'status' => $task->status,
                'due_date' => $task->due_date,
                'created_at' => $task->created_at,
                'deleted_at' => $task->deleted_at,
                'trashed' => $task->trashed(),
                'assigned_to' => $task->assignedTo ? [
                    'id' => $task->assignedTo->id,
                    'name' => $task->assignedTo->name,
                ] : null,
                'assigned_by' => $task->assignedBy ? [
                    'id' => $task->assignedBy->id,
                    'name' => $task->assignedBy->name,
                ] : null,
                'report' => $task->report ? [
                    'id' => $task->report->id,
                    'title' => $task->report->title,
                    'slug' => $task->report->slug,
                ] : null,
            ]);

        $users = User::all(['id', 'name']);
        $stats = [
            'total' => Task::count(),
            'pending' => Task::where('status', 'pending')->count(),
            'in_progress' => Task::where('status', 'in_progress')->count(),
            'completed' => Task::where('status', 'completed')->count(),
            'overdue' => Task::where('status', '!=', 'completed')->where('due_date', '<', now())->count(),
            'trashed' => Task::onlyTrashed()->count(),
        ];

        return Inertia::render('Admin/Tasks/Index', [
            'tasks' => $tasks,
            'users' => $users,
            'stats' => $stats,
            'filters' => $request->only(['status', 'priority', 'assigned_to', 'search', 'sort', 'direction', 'trashed'])
        ]);
    }

    /**
     * Show the form for creating a new task.
     */
    public function create()
    {
        $users = User::all(['id', 'name']);
        $reports = Report::where('user_id', auth()->id())
            ->orWhereHas('assignments', fn($q) => $q->where('user_id', auth()->id()))
            ->get(['id', 'title', 'slug']);
            
        return Inertia::render('Admin/Tasks/Create', [
            'users' => $users,
            'reports' => $reports
        ]);
    }

    /**
     * Store a newly created task in storage.
     */
    public function store(Request $request)
    {
        $request->validate([
            'title' => 'required|string|max:255',
            'description' => 'nullable|string',
            'assigned_to' => 'required|exists:users,id',
            'priority' => 'required|in:low,medium,high,urgent',
            'due_date' => 'nullable|date|after:today',
            'report_id' => 'nullable|exists:reports,id',
        ]);

        $task = Task::create([
            'title' => $request->title,
            'description' => $request->description,
            'assigned_by' => auth()->id(),
            'assigned_to' => $request->assigned_to,
            'priority' => $request->priority,
            'due_date' => $request->due_date,
            'report_id' => $request->report_id,
            'status' => 'pending',
        ]);

        // Log activity
        UserActivity::log(auth()->id(), 'task_created', 'task', $task->id, [
            'task_title' => $task->title,
            'assigned_to' => $task->assignedTo->name
        ]);

        // 🔔 Create notification for assigned user
        NotificationService::taskCreated($task, $request->assigned_to);

        return redirect()->route('admin.tasks.index')->with('success', 'Task created successfully.');
    }

    /**
     * Display the specified task (View single task details)
     */
    public function show(Task $task)
    {
        // Load relationships
        $task->load(['assignedTo', 'assignedBy', 'report']);
        
        // Get task activity logs
        $activities = UserActivity::where('entity_type', 'task')
            ->where('entity_id', $task->id)
            ->orderBy('created_at', 'desc')
            ->take(10)
            ->get()
            ->map(fn($activity) => [
                'action' => $activity->action,
                'user_name' => $activity->user->name,
                'created_at' => $activity->created_at,
                'details' => $activity->details,
            ]);
        
        // Get related tasks
        $relatedTasks = Task::where('assigned_to', $task->assigned_to)
            ->where('id', '!=', $task->id)
            ->limit(5)
            ->get(['id', 'title', 'status', 'priority', 'due_date']);
        
        return Inertia::render('Admin/Tasks/Show', [
            'task' => [
                'id' => $task->id,
                'title' => $task->title,
                'description' => $task->description,
                'priority' => $task->priority,
                'status' => $task->status,
                'due_date' => $task->due_date,
                'created_at' => $task->created_at,
                'updated_at' => $task->updated_at,
                'completed_at' => $task->completed_at,
                'completion_notes' => $task->completion_notes,
                'deleted_at' => $task->deleted_at,
                'trashed' => $task->trashed(),
                'assigned_to' => $task->assignedTo ? [
                    'id' => $task->assignedTo->id,
                    'name' => $task->assignedTo->name,
                    'email' => $task->assignedTo->email,
                    'avatar' => $task->assignedTo->avatar ?? null,
                ] : null,
                'assigned_by' => $task->assignedBy ? [
                    'id' => $task->assignedBy->id,
                    'name' => $task->assignedBy->name,
                ] : null,
                'report' => $task->report ? [
                    'id' => $task->report->id,
                    'title' => $task->report->title,
                    'slug' => $task->report->slug,
                    'status' => $task->report->status,
                ] : null,
            ],
            'activities' => $activities,
            'relatedTasks' => $relatedTasks,
        ]);
    }

    /**
     * Show the form for editing the specified task.
     */
    public function edit(Task $task)
    {
        $users = User::all(['id', 'name']);
        $reports = Report::all(['id', 'title', 'slug']);
            
        return Inertia::render('Admin/Tasks/Edit', [
            'task' => $task,
            'users' => $users,
            'reports' => $reports
        ]);
    }

    /**
     * Update the specified task in storage.
     */
    public function update(Request $request, Task $task)
    {
        $request->validate([
            'title' => 'required|string|max:255',
            'description' => 'nullable|string',
            'assigned_to' => 'required|exists:users,id',
            'priority' => 'required|in:low,medium,high,urgent',
            'status' => 'required|in:pending,in_progress,completed,overdue',
            'due_date' => 'nullable|date',
            'report_id' => 'nullable|exists:reports,id',
        ]);

        $oldStatus = $task->status;
        $oldAssignee = $task->assigned_to;
        
        $task->update($request->only([
            'title', 'description', 'assigned_to', 'priority', 
            'status', 'due_date', 'report_id'
        ]));

        // Set completed_at if status changed to completed
        if ($request->status === 'completed' && !$task->completed_at) {
            $task->update(['completed_at' => now()]);
        }

        // Log status change
        if ($oldStatus !== $request->status) {
            UserActivity::log(auth()->id(), 'task_status_changed', 'task', $task->id, [
                'task_title' => $task->title,
                'old_status' => $oldStatus,
                'new_status' => $request->status
            ]);

            // 🔔 Notify if task is completed
            if ($request->status === 'completed') {
                NotificationService::taskCompleted($task);
            }
        }

        // 🔔 Notify if assigned user changed
        if ($oldAssignee != $request->assigned_to) {
            NotificationService::create(
                user: $request->assigned_to,
                type: 'task_assigned',
                title: 'Task Reassigned to You',
                message: "Task \"{$task->title}\" has been reassigned to you by " . auth()->user()->name,
                notifiable: $task,
                actionUrl: route('admin.tasks.show', $task->id),
                icon: 'fa-solid fa-user-plus',
                color: '#3b82f6'
            );
        }

        // Log general update
        UserActivity::log(auth()->id(), 'task_updated', 'task', $task->id, [
            'task_title' => $task->title,
            'changes' => $request->only(['title', 'status', 'priority'])
        ]);

        return redirect()->route('admin.tasks.index')->with('success', 'Task updated successfully.');
    }

    /**
     * Remove the specified task from storage (Soft Delete).
     */
    public function destroy(Task $task)
    {
        UserActivity::log(auth()->id(), 'task_deleted', 'task', $task->id, [
            'task_title' => $task->title
        ]);

        // 🔔 Notify assigned user that task was deleted
        if ($task->assigned_to && $task->assigned_to !== auth()->id()) {
            NotificationService::create(
                user: $task->assigned_to,
                type: 'task_deleted',
                title: 'Task Deleted',
                message: "Task \"{$task->title}\" has been deleted by " . auth()->user()->name,
                notifiable: $task,
                actionUrl: route('admin.tasks.my'),
                icon: 'fa-solid fa-trash',
                color: '#ef4444'
            );
        }

        // Soft delete the task
        $task->delete();

        // 🔔 Soft delete related notifications
        NotificationService::deleteForNotifiable($task);

        return redirect()->route('admin.tasks.index')->with('success', 'Task moved to trash successfully.');
    }

    /**
     * Restore a soft-deleted task.
     */
    public function restore($id)
    {
        $task = Task::withTrashed()->findOrFail($id);
        $task->restore();

        // 🔔 Restore related notifications
        NotificationService::restoreForNotifiable($task);

        // Log activity
        UserActivity::log(auth()->id(), 'task_restored', 'task', $task->id, [
            'task_title' => $task->title
        ]);

        // 🔔 Notify assigned user that task was restored
        if ($task->assigned_to) {
            NotificationService::create(
                user: $task->assigned_to,
                type: 'task_restored',
                title: 'Task Restored',
                message: "Task \"{$task->title}\" has been restored.",
                notifiable: $task,
                actionUrl: route('admin.tasks.show', $task->id),
                icon: 'fa-solid fa-rotate-left',
                color: '#f59e0b'
            );
        }

        return redirect()->route('admin.tasks.index')->with('success', 'Task restored successfully.');
    }

    /**
     * Force delete a task permanently.
     */
    public function forceDelete($id)
    {
        $task = Task::withTrashed()->findOrFail($id);

        // Log activity before deleting
        UserActivity::log(auth()->id(), 'task_force_deleted', 'task', $task->id, [
            'task_title' => $task->title
        ]);

        // 🔔 Force delete related notifications
        NotificationService::forceDeleteForNotifiable($task);

        // Permanently delete the task
        $task->forceDelete();

        return redirect()->route('admin.tasks.index')->with('success', 'Task permanently deleted.');
    }

    /**
     * Display trashed tasks.
     */
    public function trashed(Request $request)
    {
        $tasks = Task::onlyTrashed()
            ->with(['assignedTo', 'assignedBy', 'report'])
            ->when($request->search, fn($q) => $q->where('title', 'like', "%{$request->search}%"))
            ->orderBy('deleted_at', 'desc')
            ->paginate(15)
            ->withQueryString()
            ->through(fn($task) => [
                'id' => $task->id,
                'title' => $task->title,
                'description' => $task->description,
                'priority' => $task->priority,
                'status' => $task->status,
                'due_date' => $task->due_date,
                'created_at' => $task->created_at,
                'deleted_at' => $task->deleted_at,
                'trashed' => true,
                'assigned_to' => $task->assignedTo ? [
                    'id' => $task->assignedTo->id,
                    'name' => $task->assignedTo->name,
                ] : null,
                'assigned_by' => $task->assignedBy ? [
                    'id' => $task->assignedBy->id,
                    'name' => $task->assignedBy->name,
                ] : null,
            ]);

        return Inertia::render('Admin/Tasks/Trashed', [
            'tasks' => $tasks,
            'filters' => $request->only(['search'])
        ]);
    }

    /**
     * Update task status (AJAX call)
     */
    public function updateStatus(Request $request, Task $task)
    {
        $request->validate([
            'status' => 'required|in:pending,in_progress,completed',
            'completion_notes' => 'nullable|string'
        ]);

        $oldStatus = $task->status;
        
        $task->update([
            'status' => $request->status,
            'completion_notes' => $request->completion_notes,
            'completed_at' => $request->status === 'completed' ? now() : null
        ]);

        // Log status change
        UserActivity::log(auth()->id(), 'task_status_changed', 'task', $task->id, [
            'task_title' => $task->title,
            'old_status' => $oldStatus,
            'new_status' => $request->status,
            'completion_notes' => $request->completion_notes
        ]);

        // 🔔 Notify if task is completed
        if ($request->status === 'completed' && $oldStatus !== 'completed') {
            NotificationService::taskCompleted($task);
        }

        return response()->json([
            'message' => 'Task status updated successfully',
            'task' => [
                'id' => $task->id,
                'status' => $task->status,
                'completed_at' => $task->completed_at,
            ]
        ]);
    }

    /**
     * Get tasks assigned to the authenticated user (for regular users)
     */
    public function myTasks(Request $request)
    {
        $user = auth()->user();
        
        $tasks = Task::with(['assignedBy', 'report'])
            ->where('assigned_to', $user->id)
            ->when($request->status, fn($q) => $q->where('status', $request->status))
            ->when($request->priority, fn($q) => $q->where('priority', $request->priority))
            ->when($request->search, fn($q) => $q->where('title', 'like', "%{$request->search}%"))
            ->orderByRaw("CASE WHEN status = 'overdue' THEN 0 WHEN status = 'pending' THEN 1 WHEN status = 'in_progress' THEN 2 ELSE 3 END")
            ->orderBy('due_date', 'asc')
            ->paginate(12)
            ->withQueryString()
            ->through(fn($task) => [
                'id' => $task->id,
                'title' => $task->title,
                'description' => $task->description,
                'priority' => $task->priority,
                'status' => $task->isOverdue() ? 'overdue' : $task->status,
                'due_date' => $task->due_date,
                'assigned_by' => $task->assignedBy?->name,
                'report' => $task->report ? [
                    'id' => $task->report->id,
                    'title' => $task->report->title,
                    'slug' => $task->report->slug,
                ] : null,
            ]);
        
        $stats = [
            'pending' => Task::where('assigned_to', $user->id)->where('status', 'pending')->count(),
            'in_progress' => Task::where('assigned_to', $user->id)->where('status', 'in_progress')->count(),
            'completed' => Task::where('assigned_to', $user->id)->where('status', 'completed')->count(),
            'overdue' => Task::where('assigned_to', $user->id)
                ->where('status', '!=', 'completed')
                ->where('due_date', '<', now())
                ->count(),
        ];
        
        return Inertia::render('Tasks/MyTasks', [
            'tasks' => $tasks,
            'stats' => $stats,
            'filters' => $request->only(['search', 'status', 'priority'])
        ]);
    }

    /**
     * Get task statistics for dashboard
     */
    public function getStats()
    {
        $user = auth()->user();
        
        if ($user->hasRole('admin')) {
            $stats = [
                'total' => Task::count(),
                'pending' => Task::where('status', 'pending')->count(),
                'in_progress' => Task::where('status', 'in_progress')->count(),
                'completed' => Task::where('status', 'completed')->count(),
                'overdue' => Task::where('status', '!=', 'completed')->where('due_date', '<', now())->count(),
                'trashed' => Task::onlyTrashed()->count(),
                'completion_rate' => round((Task::where('status', 'completed')->count() / max(Task::count(), 1)) * 100),
            ];
        } else {
            $stats = [
                'total' => Task::where('assigned_to', $user->id)->count(),
                'pending' => Task::where('assigned_to', $user->id)->where('status', 'pending')->count(),
                'in_progress' => Task::where('assigned_to', $user->id)->where('status', 'in_progress')->count(),
                'completed' => Task::where('assigned_to', $user->id)->where('status', 'completed')->count(),
                'overdue' => Task::where('assigned_to', $user->id)
                    ->where('status', '!=', 'completed')
                    ->where('due_date', '<', now())
                    ->count(),
                'completion_rate' => round((Task::where('assigned_to', $user->id)->where('status', 'completed')->count() / max(Task::where('assigned_to', $user->id)->count(), 1)) * 100),
            ];
        }
        
        // Get tasks by priority
        $byPriority = [
            'low' => Task::where('priority', 'low')->count(),
            'medium' => Task::where('priority', 'medium')->count(),
            'high' => Task::where('priority', 'high')->count(),
            'urgent' => Task::where('priority', 'urgent')->count(),
        ];
        
        return response()->json([
            'stats' => $stats,
            'by_priority' => $byPriority,
        ]);
    }

    /**
     * Bulk delete tasks (Soft Delete)
     */
    public function bulkDelete(Request $request)
    {
        $request->validate([
            'task_ids' => 'required|array',
            'task_ids.*' => 'exists:tasks,id',
        ]);

        $deletedCount = 0;
        foreach ($request->task_ids as $taskId) {
            $task = Task::find($taskId);
            if ($task) {
                // Log activity
                UserActivity::log(auth()->id(), 'task_deleted', 'task', $task->id, [
                    'task_title' => $task->title,
                    'bulk_delete' => true
                ]);

                // 🔔 Notify assigned user
                if ($task->assigned_to && $task->assigned_to !== auth()->id()) {
                    NotificationService::create(
                        user: $task->assigned_to,
                        type: 'task_deleted',
                        title: 'Task Deleted',
                        message: "Task \"{$task->title}\" has been deleted.",
                        notifiable: $task,
                        actionUrl: route('admin.tasks.my'),
                        icon: 'fa-solid fa-trash',
                        color: '#ef4444'
                    );
                }

                // Soft delete
                $task->delete();
                
                // 🔔 Soft delete related notifications
                NotificationService::deleteForNotifiable($task);
                
                $deletedCount++;
            }
        }

        return response()->json([
            'message' => "{$deletedCount} tasks deleted successfully",
            'deleted_count' => $deletedCount
        ]);
    }

    /**
     * Bulk assign tasks to user
     */
    public function bulkAssign(Request $request)
    {
        $request->validate([
            'task_ids' => 'required|array',
            'task_ids.*' => 'exists:tasks,id',
            'assigned_to' => 'required|exists:users,id',
        ]);

        $assignedCount = 0;
        foreach ($request->task_ids as $taskId) {
            $task = Task::find($taskId);
            if ($task) {
                $oldAssignee = $task->assigned_to;
                $task->update(['assigned_to' => $request->assigned_to]);

                // 🔔 Notify new assignee
                if ($request->assigned_to !== $oldAssignee) {
                    NotificationService::create(
                        user: $request->assigned_to,
                        type: 'task_assigned',
                        title: 'New Task Assigned',
                        message: "Task \"{$task->title}\" has been assigned to you.",
                        notifiable: $task,
                        actionUrl: route('admin.tasks.show', $task->id),
                        icon: 'fa-solid fa-tasks',
                        color: '#6366f1'
                    );
                }

                $assignedCount++;
            }
        }

        return response()->json([
            'message' => "{$assignedCount} tasks assigned successfully",
            'assigned_count' => $assignedCount
        ]);
    }

    /**
     * Bulk update task status
     */
    public function bulkStatus(Request $request)
    {
        $request->validate([
            'task_ids' => 'required|array',
            'task_ids.*' => 'exists:tasks,id',
            'status' => 'required|in:pending,in_progress,completed',
        ]);

        $updatedCount = 0;
        foreach ($request->task_ids as $taskId) {
            $task = Task::find($taskId);
            if ($task && $task->status !== $request->status) {
                $oldStatus = $task->status;
                
                $task->update([
                    'status' => $request->status,
                    'completed_at' => $request->status === 'completed' ? now() : null
                ]);

                // 🔔 Notify if completed
                if ($request->status === 'completed') {
                    NotificationService::taskCompleted($task);
                }

                $updatedCount++;
            }
        }

        return response()->json([
            'message' => "{$updatedCount} tasks updated successfully",
            'updated_count' => $updatedCount
        ]);
    }

    /**
     * Search tasks (AJAX)
     */
    public function search(Request $request)
    {
        $query = $request->get('q', '');
        
        $tasks = Task::with(['assignedTo', 'assignedBy'])
            ->where('title', 'like', "%{$query}%")
            ->orWhere('description', 'like', "%{$query}%")
            ->limit(10)
            ->get()
            ->map(fn($task) => [
                'id' => $task->id,
                'title' => $task->title,
                'status' => $task->status,
                'priority' => $task->priority,
                'assigned_to_name' => $task->assignedTo?->name,
                'trashed' => $task->trashed(),
            ]);
        
        return response()->json(['tasks' => $tasks]);
    }

    /**
     * Export tasks to CSV
     */
    public function export(Request $request)
    {
        $user = auth()->user();
        
        if ($user->hasRole('admin')) {
            $tasks = Task::with(['assignedTo', 'assignedBy'])
                ->when($request->status, fn($q) => $q->where('status', $request->status))
                ->get();
        } else {
            $tasks = Task::with(['assignedBy'])
                ->where('assigned_to', $user->id)
                ->when($request->status, fn($q) => $q->where('status', $request->status))
                ->get();
        }
        
        $filename = 'tasks_' . now()->format('Y-m-d_His') . '.csv';
        
        $callback = function() use ($tasks) {
            $handle = fopen('php://output', 'w');
            
            // Add headers
            fputcsv($handle, ['ID', 'Title', 'Description', 'Priority', 'Status', 'Assigned To', 'Assigned By', 'Due Date', 'Created At', 'Completed At']);
            
            // Add data rows
            foreach ($tasks as $task) {
                fputcsv($handle, [
                    $task->id,
                    $task->title,
                    $task->description,
                    $task->priority,
                    $task->status,
                    $task->assignedTo?->name ?? 'N/A',
                    $task->assignedBy?->name ?? 'N/A',
                    $task->due_date?->format('Y-m-d') ?? 'N/A',
                    $task->created_at->format('Y-m-d H:i:s'),
                    $task->completed_at?->format('Y-m-d H:i:s') ?? 'N/A',
                ]);
            }
            
            fclose($handle);
        };
        
        return response()->stream($callback, 200, [
            'Content-Type' => 'text/csv',
            'Content-Disposition' => 'attachment; filename="' . $filename . '"',
        ]);
    }

    /**
     * Export tasks to PDF
     */
    public function exportPdf(Request $request)
    {
        // You can implement PDF export using packages like barryvdh/laravel-dompdf
        // or spatie/laravel-pdf
        $user = auth()->user();
        
        if ($user->hasRole('admin')) {
            $tasks = Task::with(['assignedTo', 'assignedBy'])->get();
        } else {
            $tasks = Task::with(['assignedBy'])
                ->where('assigned_to', $user->id)
                ->get();
        }
        
        // Placeholder for PDF export
        // $pdf = PDF::loadView('exports.tasks', compact('tasks'));
        // return $pdf->download('tasks_' . now()->format('Y-m-d') . '.pdf');
        
        return back()->with('info', 'PDF export feature coming soon.');
    }

    /**
     * Export tasks to Excel
     */
    public function exportExcel(Request $request)
    {
        // You can implement Excel export using packages like maatwebsite/excel
        $user = auth()->user();
        
        if ($user->hasRole('admin')) {
            $tasks = Task::with(['assignedTo', 'assignedBy'])->get();
        } else {
            $tasks = Task::with(['assignedBy'])
                ->where('assigned_to', $user->id)
                ->get();
        }
        
        // Placeholder for Excel export
        // return Excel::download(new TasksExport($tasks), 'tasks_' . now()->format('Y-m-d') . '.xlsx');
        
        return back()->with('info', 'Excel export feature coming soon.');
    }
