    from { transform: translate(0,0) scale(1); }
    to { transform: translate(-50px, -30px) scale(1.08); }
}
@keyframes floatC {
    from { transform: translate(-50%, -50%) scale(1); }
    to { transform: translate(-50%, -50%) scale(1.15) rotate(30deg); }
}
</style>
