</template>

<script setup>
import { ref, onMounted, watch, onBeforeUnmount } from 'vue'
import { router } from '@inertiajs/vue3'
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'
import Chart from 'chart.js/auto'

const props = defineProps({
    reportStats: Object,
    userStats: Object,
    taskStats: Object,
    activityStats: Object,
    sharingStats: Object,
    chartData: Object,
    period: Number
})

const period = ref(props.period || 30)
const reportsChartRef = ref(null)
const usersChartRef = ref(null)
const tasksChartRef = ref(null)
const typesChartRef = ref(null)

let reportsChart = null
let usersChart = null
let tasksChart = null
let typesChart = null

const changePeriod = () => {
    router.get(route('admin.analytics.index'), { period: period.value }, { preserveState: true, preserveScroll: true })
}

const exportAnalytics = () => {
    window.open(route('admin.analytics.export', { period: period.value, type: 'reports' }), '_blank')
}

const initCharts = () => {
    // Reports Chart
    const reportsCtx = document.getElementById('reportsChart')?.getContext('2d')
    if (reportsCtx && props.chartData?.reports_created) {
        if (reportsChart) reportsChart.destroy()
        reportsChart = new Chart(reportsCtx, {
            type: 'line',
            data: {
                labels: props.chartData.reports_created.labels,
                datasets: [{
                    label: 'Reports Created',
                    data: props.chartData.reports_created.values,
                    borderColor: '#6366f1',
                    backgroundColor: 'rgba(99, 102, 241, 0.1)',
                    fill: true,
                    tension: 0.4,
                    pointBackgroundColor: '#6366f1',
                    pointBorderColor: '#fff',
                    pointBorderWidth: 2,
                    pointRadius: 4,
                    pointHoverRadius: 6
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false },
                    tooltip: {
                        backgroundColor: '#1e293b',
                        titleColor: '#f1f5f9',
                        bodyColor: '#94a3b8',
                        borderColor: '#6366f1',
                        borderWidth: 1,
                        cornerRadius: 8,
                        padding: 10
                    }
                },
                scales: {
                    y: {
                        grid: { color: 'rgba(0, 0, 0, 0.05)' },
                        ticks: { stepSize: 1 }
                    },
                    x: {
                        grid: { display: false },
                        ticks: { maxRotation: 45, minRotation: 45 }
                    }
                }
            }
        })
    }

    // Users Chart
    const usersCtx = document.getElementById('usersChart')?.getContext('2d')
    if (usersCtx && props.chartData?.user_growth) {
        if (usersChart) usersChart.destroy()
        usersChart = new Chart(usersCtx, {
            type: 'line',
            data: {
                labels: props.chartData.user_growth.labels,
                datasets: [{
                    label: 'New Users',
                    data: props.chartData.user_growth.values,
                    borderColor: '#10b981',
                    backgroundColor: 'rgba(16, 185, 129, 0.1)',
                    fill: true,
                    tension: 0.4,
                    pointBackgroundColor: '#10b981',
                    pointBorderColor: '#fff',
                    pointBorderWidth: 2,
                    pointRadius: 4,
                    pointHoverRadius: 6
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false },
                    tooltip: {
                        backgroundColor: '#1e293b',
                        titleColor: '#f1f5f9',
                        bodyColor: '#94a3b8',
                        borderColor: '#10b981',
                        borderWidth: 1,
                        cornerRadius: 8,
                        padding: 10
                    }
                },
                scales: {
                    y: {
                        grid: { color: 'rgba(0, 0, 0, 0.05)' },
                        ticks: { stepSize: 1 }
                    },
                    x: {
                        grid: { display: false },
                        ticks: { maxRotation: 45, minRotation: 45 }
                    }
                }
            }
        })
    }

    // Tasks Chart
    const tasksCtx = document.getElementById('tasksChart')?.getContext('2d')
    if (tasksCtx && props.chartData?.task_completion) {
        if (tasksChart) tasksChart.destroy()
        tasksChart = new Chart(tasksCtx, {
            type: 'bar',
            data: {
                labels: props.chartData.task_completion.labels,
                datasets: [
                    {
                        label: 'Tasks Created',
                        data: props.chartData.task_completion.created,
                        backgroundColor: '#6366f1',
                        borderRadius: 6,
                        barPercentage: 0.6,
                        categoryPercentage: 0.8
                    },
                    {
                        label: 'Tasks Completed',
                        data: props.chartData.task_completion.completed,
                        backgroundColor: '#10b981',
                        borderRadius: 6,
                        barPercentage: 0.6,
                        categoryPercentage: 0.8
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'top',
                        labels: { usePointStyle: true, boxWidth: 8 }
                    },
                    tooltip: {
                        backgroundColor: '#1e293b',
                        titleColor: '#f1f5f9',
                        bodyColor: '#94a3b8',
                        borderWidth: 1,
                        cornerRadius: 8,
                        padding: 10
                    }
                },
                scales: {
                    y: {
                        grid: { color: 'rgba(0, 0, 0, 0.05)' },
                        ticks: { stepSize: 1, precision: 0 }
                    },
                    x: {
                        grid: { display: false },
                        ticks: { maxRotation: 45, minRotation: 45 }
                    }
                }
            }
        })
    }

    // Types Chart
    const typesCtx = document.getElementById('typesChart')?.getContext('2d')
    if (typesCtx && props.chartData?.popular_report_types) {
        if (typesChart) typesChart.destroy()
        typesChart = new Chart(typesCtx, {
            type: 'doughnut',
            data: {
                labels: props.chartData.popular_report_types.labels,
                datasets: [{
                    data: props.chartData.popular_report_types.values,
                    backgroundColor: ['#6366f1', '#8b5cf6', '#10b981', '#f59e0b', '#ef4444', '#06b6d4', '#ec4899'],
                    borderWidth: 0,
                    hoverOffset: 10
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: {
                            usePointStyle: true,
                            boxWidth: 8,
                            padding: 12,
                            font: { size: 11 }
                        }
                    },
                    tooltip: {
                        backgroundColor: '#1e293b',
                        titleColor: '#f1f5f9',
                        bodyColor: '#94a3b8',
                        borderWidth: 1,
                        cornerRadius: 8,
                        padding: 10,
                        callbacks: {
                            label: (context) => {
                                const label = context.label || ''
                                const value = context.raw || 0
                                const total = context.dataset.data.reduce((a, b) => a + b, 0)
                                const percentage = ((value / total) * 100).toFixed(1)
                                return `${label}: ${value} (${percentage}%)`
                            }
                        }
                    }
                },
                cutout: '60%'
            }
        })
    }
}

onMounted(() => {
    initCharts()
})

watch(() => props.chartData, () => {
    initCharts()
}, { deep: true })

onBeforeUnmount(() => {
    if (reportsChart) reportsChart.destroy()
    if (usersChart) usersChart.destroy()
    if (tasksChart) tasksChart.destroy()
    if (typesChart) typesChart.destroy()
})
</script>

