import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'

const props = defineProps({
    users: Array,
    reports: Array
})

const form = useForm({
    title: '',
    description: '',
    assigned_to: '',
    priority: 'medium',
    due_date: '',
    report_id: ''
})

const submit = () => {
    form.post(route('admin.tasks.store'))
}
</script>

